"""Pipeline with ordering dependency: process must run after init."""

_log = []
_initialized = False
_buffer = []


def reset():
    global _initialized, _buffer
    _log.clear()
    _buffer.clear()
    _initialized = False


def init():
    global _initialized, _buffer
    _initialized = True
    _log.append("init")
    # Process all buffered items
    for item in _buffer:
        _log.append(f"processed:{item}")
    _buffer.clear()


def process(item):
    """Buffer items if not initialized; process immediately if initialized."""
    if not _initialized:
        _log.append(f"error:not_init:{item}")
        _buffer.append(item)
        return False
    _log.append(f"processed:{item}")
    return True


def shutdown():
    _log.append("shutdown")
    return list(_log)


def get_log():
    return list(_log)


def run_steps(steps):
    results = []
    for fn, args in steps:
        results.append(fn(*args))
    return results


def correct_order():
    """init -> process(a) -> process(b) -> shutdown. Correct."""
    reset()
    run_steps([
        (init, ()),
        (process, ("a",)),
        (process, ("b",)),
        (shutdown, ()),
    ])
    return get_log()


def broken_order():
    """process(a) runs BEFORE init. BUG: item a is lost."""
    reset()
    run_steps([
        (process, ("a",)),
        (init, ()),
        (process, ("b",)),
        (shutdown, ()),
    ])
    return get_log()

"""Resource transfers with lock-ordering deadlock, simulated via steps."""

_locks = {}
_state = {"A": 100, "B": 100}


def reset():
    _locks.clear()
    _state["A"] = 100
    _state["B"] = 100


def acquire(resource):
    """Simulate lock. Raises RuntimeError if already held (deadlock)."""
    if _locks.get(resource):
        raise RuntimeError(f"deadlock: {resource} already locked")
    _locks[resource] = True


def release(resource):
    _locks[resource] = False


def get_state():
    return dict(_state)


def run_steps(steps):
    results = []
    for fn, args in steps:
        results.append(fn(*args))
    return results


def make_transfer_a_to_b_steps(amount):
    """Transfer A→B: lock A first, then B."""

    def step_lock_a():
        acquire("A")
        return "locked_A"

    def step_lock_b_and_transfer():
        acquire("B")
        _state["A"] -= amount
        _state["B"] += amount
        release("B")
        release("A")
        return "transferred_a_to_b"

    return step_lock_a, step_lock_b_and_transfer


def make_transfer_b_to_a_steps(amount):
    """Transfer B→A: lock B first, then A (fixed order)."""

    def step_lock_b():
        acquire("B")
        return "locked_B"

    def step_lock_a_and_transfer():
        acquire("A")  # Fixed: acquire A first to prevent deadlock
        _state["B"] -= amount
        _state["A"] += amount
        release("A")
        release("B")
        return "transferred_b_to_a"

    return step_lock_b, step_lock_a_and_transfer


def sequential_transfers():
    """A→B then B→A. Sequential: works fine."""
    reset()
    lock_ab, do_ab = make_transfer_a_to_b_steps(10)
    lock_ba, do_ba = make_transfer_b_to_a_steps(10)
    run_steps([
        (lock_ab, ()), (do_ab, ()),
        (lock_ba, ()), (do_ba, ()),
    ])
    return get_state()


def interleaved_transfers():
    """A→B and B→A interleaved: DEADLOCK."""
    reset()
    lock_ab, do_ab = make_transfer_a_to_b_steps(10)
    lock_ba, do_ba = make_transfer_b_to_a_steps(10)
    try:
        run_steps([
            (lock_ab, ()),   # A→B locks A
            (lock_ba, ()),   # B→A locks B
            (do_ab, ()),     # A→B tries to lock B — deadlock
            (do_ba, ()),     # never reached
        ])
        return get_state()
    except RuntimeError as e:
        return {"error": str(e)}

